package br.com.muxe.minigame.api.cosmetic.animation;

import br.com.muxe.core.bukkit.cosmetic.animation.SignedSkin;
import java.util.List;

final class WitchSkins {

    static final List<SignedSkin> ALL = List.of(
        new SignedSkin(
            "",
            ""),
        new SignedSkin(
            "",
            ""),
        new SignedSkin(
            "",
            ""),
        new SignedSkin(
            "",
            "")
    );

    private WitchSkins() {
    }

    static SignedSkin of(int index) {
        return ALL.get(Math.floorMod(index, ALL.size()));
    }
}
